from collections.abc import MutableMapping
import json
import math
import threading
import time


def check_rate_limit(buckets: MutableMapping[str, dict[str, float]], key: str, capacity: float=10.0, refill_rate: float=1.0, cost: float=1.0, now: float | None=None) -> tuple[bool, float]:
    if capacity <= 0 or refill_rate <= 0 or cost <= 0:
        raise ValueError('capacity, refill_rate and cost must be positive')
    if cost > capacity:
        raise ValueError('cost can never be satisfied: it exceeds capacity')
    now = time.monotonic() if now is None else now
    bucket = buckets.get(key)
    if bucket is None:
        bucket = buckets[key] = {'tokens': float(capacity), 'last': now}
    elapsed = max(0.0, now - bucket['last'])
    bucket['tokens'] = min(float(capacity), bucket['tokens'] + elapsed * refill_rate)
    bucket['last'] = now
    if bucket['tokens'] >= cost:
        bucket['tokens'] -= cost
        return (True, 0.0)
    return (False, (cost - bucket['tokens']) / refill_rate)


def get_client_key(environ: dict) -> str:
    """Identify the client by API key if present, otherwise by IP address."""
    api_key = environ.get("HTTP_X_API_KEY")
    if api_key:
        return "key:" + api_key
    # Only trust X-Forwarded-For if you run behind a proxy you control.
    forwarded = environ.get("HTTP_X_FORWARDED_FOR")
    if forwarded:
        return "ip:" + forwarded.split(",")[0].strip()
    return "ip:" + environ.get("REMOTE_ADDR", "unknown")


def make_rate_limit_middleware(app, requests_per_minute: int = 60):
    """Wrap any WSGI app (Flask, Django, Falcon, ...) with per-client rate limiting.

    Usage (Flask): app.wsgi_app = make_rate_limit_middleware(app.wsgi_app, 100)
    """
    buckets: dict[str, dict[str, float]] = {}
    lock = threading.Lock()
    refill_rate = requests_per_minute / 60.0

    def middleware(environ, start_response):
        key = get_client_key(environ)
        with lock:
            allowed, retry_after = check_rate_limit(
                buckets, key, capacity=requests_per_minute, refill_rate=refill_rate
            )
        if allowed:
            return app(environ, start_response)

        body = json.dumps({
            "error": "rate_limit_exceeded",
            "message": "Too many requests. Please retry later.",
        }).encode("utf-8")
        start_response("429 Too Many Requests", [
            ("Content-Type", "application/json"),
            ("Content-Length", str(len(body))),
            ("Retry-After", str(max(1, math.ceil(retry_after)))),
        ])
        return [body]

    return middleware

